package com.taskflow.app.ui;
import androidx.lifecycle.*;import org.json.*;import java.net.*;import java.io.*;import java.util.concurrent.*;
public class AiViewModel extends ViewModel {
 public final MutableLiveData<String> status=new MutableLiveData<>("");public final MutableLiveData<JSONObject> result=new MutableLiveData<>();public final MutableLiveData<Boolean> busy=new MutableLiveData<>(false);private final ExecutorService io=Executors.newSingleThreadExecutor();private volatile HttpURLConnection connection;private volatile boolean closed;
 public void request(String path,JSONObject payload){if(Boolean.TRUE.equals(busy.getValue()))return;busy.setValue(true);status.setValue("正在请求 DeepSeek…");io.execute(()->{try{connection=(HttpURLConnection)new URL("http://127.0.0.1:8765"+path).openConnection();connection.setConnectTimeout(5000);connection.setReadTimeout(60000);connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");try(OutputStream out=connection.getOutputStream()){out.write(payload.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}int code=connection.getResponseCode();InputStream stream=code==200?connection.getInputStream():connection.getErrorStream();if(stream==null)throw new IOException("后端没有返回内容");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=stream){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(bytes.size()+n>100000)throw new IOException("响应过大");bytes.write(b,0,n);}}JSONObject response=new JSONObject(bytes.toString("UTF-8"));if(code!=200)throw new IOException(response.optString("error","请求失败"));if(!closed){response.put("kind",path);result.postValue(response);status.postValue("已生成，请核对内容");}}catch(Exception e){if(!closed)status.postValue("请求失败："+e.getMessage()+"。可继续手动创建。");}finally{if(connection!=null)connection.disconnect();if(!closed)busy.postValue(false);}});}
 public void consume(){result.setValue(null);}protected void onCleared(){closed=true;if(connection!=null)connection.disconnect();io.shutdownNow();}
}
